package org.telegram.messenger.tetogram;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class SectionOpeningPolicyTest {
 @Test public void absentModeKeepsFloatingDefault(){assertEquals("floating",new SectionConfig().openingMode);assertEquals("floating",SectionConfig.decode("").openingMode);assertEquals("floating",SectionConfig.decode("schema=1\n").openingMode);assertEquals("floating",SectionConfig.decode("schema=2\n").openingMode);}
 @Test public void unknownModeHasSafeFallback(){assertEquals("floating",SectionConfig.decode("schema=2\nopeningMode=future\n").openingMode);}
 @Test public void roundTripKeepsAllExistingData(){SectionConfig c=new SectionConfig();SectionConfig.Section s=c.add("Friends");s.chats.add(42L);s.icon="📩";s.excluded.add(43L);SectionConfig.Folder f=c.addFolder("Games");s.tabs.add(f.id);s.lastFolder=f.id;c.defaultId=s.id;c.openingMode="chats";c.openingModeRevision=8;SectionConfig d=SectionConfig.decode(c.encode());assertEquals("chats",d.openingMode);assertEquals(8,d.openingModeRevision);assertEquals(s.id,d.defaultId);assertEquals(s.icon,d.section(s.id).icon);assertEquals(s.chats,d.section(s.id).chats);assertEquals(s.excluded,d.section(s.id).excluded);assertEquals(f.id,d.section(s.id).lastFolder);assertEquals(s.tabs,d.section(s.id).tabs);}
 @Test public void legacyMigrationPreservesStableIdsAndFolders(){SectionConfig c=new SectionConfig();SectionConfig.Section section=c.add("Old");SectionConfig.Folder folder=c.addFolder("Local");section.tabs.add(folder.id);section.chats.add(77L);section.icon="📩";section.lastFolder=folder.id;c.openingMode="chats";String old=c.encode().replace("schema=2","schema=1").replaceAll("(?m)^openingMode.*\\R","");SectionConfig migrated=SectionConfig.decode(old);assertEquals("floating",migrated.openingMode);assertEquals(section.id,migrated.initial());assertEquals(section.chats,migrated.section(section.id).chats);assertEquals(section.icon,migrated.section(section.id).icon);assertEquals(folder.id,migrated.section(section.id).lastFolder);}
 @Test public void staleTabWritePreservesNewerOpeningChoice(){SectionConfig old=new SectionConfig(),latest=new SectionConfig();latest.openingMode="chats";latest.openingModeRevision=2;old.preserveNewerOpeningMode(latest);assertEquals("chats",old.openingMode);assertEquals(2,old.openingModeRevision);old.openingModeRevision=3;old.openingMode="floating";old.preserveNewerOpeningMode(latest);assertEquals("floating",old.openingMode);}
 @Test public void accountNamespacesAndConfigsStaySeparate(){SectionConfig a=new SectionConfig(),b=new SectionConfig();a.openingMode="chats";assertNotEquals(SectionConfig.accountNamespace(10),SectionConfig.accountNamespace(20));assertEquals("floating",SectionConfig.decode(b.encode()).openingMode);assertEquals("chats",SectionConfig.decode(a.encode()).openingMode);}
 @Test public void onlyRepeatOnActiveChatsInModeTwoToggles(){assertTrue(SectionOpeningPolicy.repeatToggles("chats",true,true,true,true));assertFalse(SectionOpeningPolicy.repeatToggles("floating",true,true,true,true));assertFalse(SectionOpeningPolicy.repeatToggles("chats",false,true,true,true));}
 @Test public void inactiveDestroyedSearchArchiveSelectionOrOtherAccountDoNotToggle(){assertFalse(SectionOpeningPolicy.repeatToggles("chats",true,false,true,true));assertFalse(SectionOpeningPolicy.repeatToggles("chats",true,true,false,true));assertFalse(SectionOpeningPolicy.repeatToggles("chats",true,true,true,false));}
 @Test public void menuIsCenteredAndClampedToSafeHorizontalBounds(){assertEquals(48,SectionOpeningPolicy.left(80,64,400,0,0));assertEquals(40,SectionOpeningPolicy.left(30,64,400,40,20));assertEquals(316,SectionOpeningPolicy.left(395,64,400,40,20));}
 @Test public void longMenuEndsAboveNavigationAndStaysBelowHeader(){assertEquals(300,SectionOpeningPolicy.height(300,600,80,8));assertEquals(112,SectionOpeningPolicy.height(900,200,80,8));assertEquals(0,SectionOpeningPolicy.height(900,70,80,8));}
 @Test public void repeatedRequestsAndLateAnimationCallbacksRemainFenced(){SectionMenuState s=new SectionMenuState();long first=s.request(true),second=s.request(false),third=s.request(true);assertFalse(s.finish(first));assertFalse(s.finish(second));assertTrue(s.finish(third));assertTrue(s.targetOpen());s.cancel();assertFalse(s.targetOpen());assertFalse(s.finish(third));}
}
